from pathlib import Path
import re

p = Path('marwa.html')
s = p.read_text(encoding='utf-8')

s = s.replace('رحلة خاصة جدًا • لمروى فقط 🤍', 'رحلة خاصة جدًا • لمروى 🤍')
s = s.replace('https://cdn1.suno.ai/5878b6d7-f65b-4fd2-87a3-d978e96fe324.mp3', 'https://cdn1.suno.ai/de8cdd97-18b4-423f-87e3-da4d6dbd8667.mp3')

# Keep study analysis fully manual.
manual_analysis = """function studyAnalysis(){const o=$('studyAnalysisOverlay'),pct=$('analysisPercent'),fill=$('analysisFill'),st=$('analysisStatus'),res=$('analysisResult'),btn=$('analysisContinue');o.classList.add('show');o.setAttribute('aria-hidden','false');res.classList.remove('show');if(btn){btn.disabled=false;btn.textContent='اضغطي هنا عشان نكمّل 👀'}const steps=[{p:12,t:'فتح ملفات الرحلة...'},{p:46,t:'حساب عدد مرات «خلاص… أنا تعبت» 😂'},{p:87,t:'فحص مستوى الصبر والتحمّل...'},{p:99,t:'لحظة… النظام يحاول يستوعب كل هذا 👀'}];let i=0;function run(){const x=steps[i];pct.textContent=x.p+'%';fill.style.width=x.p+'%';st.textContent=x.t;if(i<steps.length-1){i++;setTimeout(run,780);return}setTimeout(()=>{st.textContent='خذي وقتك واقرئي النتيجة 👇';res.classList.add('show');hearts(6)},1350)}requestAnimationFrame(()=>{fill.style.width='12%';run()})}function finishStudyAnalysis(){const o=$('studyAnalysisOverlay');o.classList.remove('show');o.setAttribute('aria-hidden','true');go(4)}"""
pat = r"function studyAnalysis\(\)\{.*?\}function q4\("
if re.search(pat, s, flags=re.S):
    s = re.sub(pat, manual_analysis + 'function q4(', s, count=1, flags=re.S)

s = s.replace('<button class="btn gold hide" id="n4" onclick="go(5)">فتح الملف السري 🔓</button>', '<button class="btn gold hide" id="n4" onclick="openGiftChoice()">اختاري هديتك 🎁</button>', 1)
s = s.replace('<button class="btn hide" id="n5" onclick="go(6)">التالي 🤍</button>', '<button class="btn hide" id="n5" onclick="showPrideTyping()">التالي 🤍</button>', 1)
s = s.replace('<button class="btn gold hide" id="n7" onclick="go(8)">استلمي الجائزة الكبرى ✨</button>', '<button class="btn gold hide" id="n7" onclick="openAudioGate()">استلمي الجائزة الكبرى ✨</button>', 1)

css_marker = '/* MARWA-INTERACTIVE-V2 */'
if css_marker not in s:
    css = """/* MARWA-INTERACTIVE-V2 */.moment-overlay{position:fixed;inset:0;z-index:60;display:grid;place-items:center;padding:18px;background:radial-gradient(circle at 50% 12%,rgba(210,184,109,.13),transparent 28%),linear-gradient(155deg,#211118,#10090d);opacity:0;visibility:hidden;transition:opacity .35s ease;overflow-y:auto}.moment-overlay.show{opacity:1;visibility:visible}.moment-card{width:min(590px,100%);padding:26px 20px;border-radius:28px;background:rgba(255,255,255,.075);border:1px solid rgba(255,255,255,.12);box-shadow:0 30px 90px rgba(0,0,0,.4);backdrop-filter:blur(18px);color:#fff;text-align:center}.moment-card h2{color:#fff}.moment-card p{color:#e7d8dd}.moment-hidden{display:none!important}.pop-btn{margin-top:16px;animation:momentPop .5s both,momentPulse 1.8s .65s ease-in-out infinite;transform-origin:center}@keyframes momentPop{0%{opacity:0;transform:scale(.72) translateY(10px)}70%{opacity:1;transform:scale(1.055)}100%{opacity:1;transform:scale(1)}}@keyframes momentPulse{0%,100%{transform:scale(1)}50%{transform:scale(1.025)}}.gift-picks{display:grid;grid-template-columns:repeat(3,1fr);gap:11px;margin:22px 0}.gift-pick{border:1px solid rgba(255,255,255,.13);background:rgba(255,255,255,.075);border-radius:21px;padding:18px 8px;color:#fff;cursor:pointer;min-height:120px}.gift-pick .gift-emoji{display:block;font-size:50px;transition:.25s}.gift-pick.selected{background:rgba(201,168,93,.18);border-color:rgba(238,212,141,.55);transform:scale(1.025)}.gift-pick:disabled{opacity:.35}.gift-result{display:none;margin-top:14px;padding:16px;border-radius:18px;background:rgba(255,255,255,.08);line-height:1.8;color:#fff3dc}.gift-result.show{display:block;animation:momentPop .45s both}.gift-result strong{color:#f1d797}.stats-list{display:grid;gap:9px;text-align:right;margin:18px 0}.stat-row{opacity:0;transform:translateY(8px);transition:.45s;background:rgba(255,255,255,.065);padding:12px 14px;border-radius:15px;display:flex;justify-content:space-between;gap:12px}.stat-row.show{opacity:1;transform:none}.stat-row b{color:#f1d797;white-space:nowrap}.stat-bars{display:grid;gap:14px;margin-top:17px;text-align:right}.stat-line{opacity:0;transition:.45s}.stat-line.show{opacity:1}.stat-track{height:10px;background:rgba(255,255,255,.1);border-radius:99px;overflow:hidden;margin-top:7px}.stat-fill{height:100%;width:0;border-radius:99px;background:linear-gradient(90deg,#b66c7e,#d8bd75);transition:width 1s ease}.grad-result{opacity:0;transform:scale(.93);transition:.5s;margin-top:18px;padding:17px;border-radius:18px;background:rgba(210,184,109,.13);font-size:20px;font-weight:900;color:#f6e4ae}.grad-result.show{opacity:1;transform:scale(1)}.typing-screen{background:radial-gradient(circle at 50% 35%,rgba(130,65,83,.18),transparent 32%),#0b0809}.typing-lead{font-size:16px;color:#bdaeb3!important;margin-bottom:20px}.typing-text{min-height:100px;font-size:clamp(25px,7vw,40px);font-weight:900;line-height:1.65;color:#fff}.typing-caret:after{content:'|';margin-right:3px;color:#e9cb80;animation:blink .7s steps(1) infinite}@keyframes blink{50%{opacity:0}}.audio-file{margin:17px 0;text-align:right;background:#0d0b0c;border-radius:18px;padding:16px}.audio-file-name{font-family:Consolas,monospace;color:#f1d797;font-size:17px;margin-bottom:15px;direction:ltr;text-align:left}.audio-meta{display:grid;grid-template-columns:1fr 1fr;gap:9px}.audio-meta div{background:rgba(255,255,255,.05);padding:10px;border-radius:12px}.audio-meta small{display:block;color:#9e8e93;margin-bottom:3px}.gate-status{margin-top:13px;font-weight:900;color:#e8c96f}.gate-ready{color:#8fe0b5!important}@media(max-width:480px){.gift-picks{gap:7px}.gift-pick{padding:15px 4px;min-height:105px}.gift-pick .gift-emoji{font-size:42px}.audio-meta{grid-template-columns:1fr}.moment-card{padding:23px 15px}}"""
    s = s.replace('</style>', css + '</style>', 1)

if 'id="giftChoiceOverlay"' not in s:
    overlays = """<div class="moment-overlay" id="giftChoiceOverlay" aria-hidden="true"><div class="moment-card"><span class="chip">🎁 اختيار مصيري جدًا</span><h2>اختاري هدية وحدة فقط…</h2><p><b>اختاري بحكمة 👀😂</b></p><div class="gift-picks" id="giftPicks"><button class="gift-pick" onclick="chooseGiftBox(this,1)"><span class="gift-emoji">🎁</span><small>الصندوق 1</small></button><button class="gift-pick" onclick="chooseGiftBox(this,2)"><span class="gift-emoji">🎁</span><small>الصندوق 2</small></button><button class="gift-pick" onclick="chooseGiftBox(this,3)"><span class="gift-emoji">🎁</span><small>الصندوق 3</small></button></div><div class="gift-result" id="giftChoiceResult"></div><button class="btn gold pop-btn moment-hidden" id="giftChoiceContinue" onclick="enterSecretFile()">افتحي الملف السري 🔓</button></div></div><div class="moment-overlay" id="statsOverlay" aria-hidden="true"><div class="moment-card"><span class="chip">📊 ملف إحصائي سري</span><h2>تحليل الرحلة الجامعية لمروى 😂</h2><div class="stats-list"><div class="stat-row" data-stat><span>☕ القهوة المستهلكة</span><b>غير قابلة للحساب</b></div><div class="stat-row" data-stat><span>😩 «أنا تعبت»</span><b>+999</b></div><div class="stat-row" data-stat><span>👀 مرات فكرت تستسلم</span><b>سرية جدًا</b></div></div><div class="stat-bars"><div class="stat-line" data-statline><div>نسبة الاستسلام الفعلية: <b>0%</b></div><div class="stat-track"><div class="stat-fill" id="giveUpBar"></div></div></div><div class="stat-line" data-statline><div>نسبة الوصول: <b>100% ✅</b></div><div class="stat-track"><div class="stat-fill" id="arrivalBar"></div></div></div></div><div class="grad-result" id="gradResult">الحالة الحالية: خريجة رسميًا 🎓🤍</div><button class="btn gold pop-btn moment-hidden" id="statsContinue" onclick="finishStats()">كمّلي قراءة الملف 👀</button></div></div><div class="moment-overlay typing-screen" id="typingOverlay" aria-hidden="true"><div class="moment-card" style="background:rgba(255,255,255,.035)"><p class="typing-lead">في شيء كنت أبغى أقوله لك…</p><div class="typing-text typing-caret" id="typingText"></div><button class="btn gold pop-btn moment-hidden" id="typingContinue" onclick="finishPrideTyping()">كمّلي 🤍</button></div></div><div class="moment-overlay" id="audioGateOverlay" aria-hidden="true"><div class="moment-card"><span class="chip">🎧 ملف جديد</span><h2>تم العثور على ملف صوتي غير معروف.</h2><div class="audio-file"><div class="audio-file-name">MARWA_FINAL_GIFT.mp3</div><div class="audio-meta"><div><small>TYPE</small>Private Audio</div><div><small>OWNER</small>مروى 🤍</div><div><small>SIZE</small>مفاجأة واحدة</div><div><small>SENDER</small>شخص فخور جدًا فيها 👀</div></div><div class="gate-status" id="audioGateStatus">STATUS: LOCKED 🔒</div></div><button class="btn gold pop-btn moment-hidden" id="audioGateContinue" onclick="finishAudioGate()">فتح الملف 🎧</button></div></div>"""
    marker = '<div class="analysis-overlay" id="studyAnalysisOverlay"'
    s = s.replace(marker, overlays + marker, 1)

if 'function openGiftChoice()' not in s:
    js = """function showMoment(id){const o=$(id);o.classList.add('show');o.setAttribute('aria-hidden','false')}function hideMoment(id){const o=$(id);o.classList.remove('show');o.setAttribute('aria-hidden','true')}function openGiftChoice(){const picks=document.querySelectorAll('#giftPicks .gift-pick'),res=$('giftChoiceResult'),next=$('giftChoiceContinue');picks.forEach(x=>{x.disabled=false;x.classList.remove('selected')});res.classList.remove('show');res.innerHTML='';next.classList.add('moment-hidden');showMoment('giftChoiceOverlay')}function chooseGiftBox(btn,n){document.querySelectorAll('#giftPicks .gift-pick').forEach(x=>x.disabled=true);btn.disabled=false;btn.classList.add('selected');const texts={1:'🎓 <strong>شهادة صبر على الدراسة</strong><br>تم اعتمادها رسميًا بعد سنوات من المعاناة 😂',2:'😴 <strong>رصيد نوم غير محدود</strong><br>صالح للاستخدام فورًا بعد التخرج.',3:'👀❤️ <strong>المفاجأة الحقيقية لسه قدامك…</strong><br>وهذا الصندوق يعرف أكثر مما يقول.'};const res=$('giftChoiceResult');res.innerHTML=texts[n];res.classList.add('show');$('giftChoiceContinue').classList.remove('moment-hidden');hearts(5)}function enterSecretFile(){hideMoment('giftChoiceOverlay');go(5);setTimeout(startSecretStats,350)}function startSecretStats(){const rows=[...document.querySelectorAll('#statsOverlay [data-stat]')],lines=[...document.querySelectorAll('#statsOverlay [data-statline]')];rows.forEach(x=>x.classList.remove('show'));lines.forEach(x=>x.classList.remove('show'));$('giveUpBar').style.width='0%';$('arrivalBar').style.width='0%';$('gradResult').classList.remove('show');$('statsContinue').classList.add('moment-hidden');showMoment('statsOverlay');rows.forEach((x,i)=>setTimeout(()=>x.classList.add('show'),450+i*520));setTimeout(()=>lines[0].classList.add('show'),2150);setTimeout(()=>{lines[1].classList.add('show');$('arrivalBar').style.width='100%'},2750);setTimeout(()=>{$('gradResult').classList.add('show');hearts(7)},3650);setTimeout(()=>$('statsContinue').classList.remove('moment-hidden'),4300)}function finishStats(){hideMoment('statsOverlay')}let marwaTypingTimer=null;function showPrideTyping(){showMoment('typingOverlay');const out=$('typingText'),btn=$('typingContinue'),text='أنا فعلًا فخور فيك يا مروى. 🤍';out.textContent='';out.classList.add('typing-caret');btn.classList.add('moment-hidden');if(marwaTypingTimer)clearInterval(marwaTypingTimer);let i=0;setTimeout(()=>{marwaTypingTimer=setInterval(()=>{out.textContent+=text[i]||'';i++;if(i>=text.length){clearInterval(marwaTypingTimer);marwaTypingTimer=null;out.classList.remove('typing-caret');setTimeout(()=>{btn.classList.remove('moment-hidden');hearts(6)},500)}},80)},650)}function finishPrideTyping(){hideMoment('typingOverlay');go(6)}let audioGateTimer=null;function openAudioGate(){const st=$('audioGateStatus'),btn=$('audioGateContinue');st.textContent='STATUS: LOCKED 🔒';st.classList.remove('gate-ready');btn.classList.add('moment-hidden');showMoment('audioGateOverlay');if(audioGateTimer)clearTimeout(audioGateTimer);audioGateTimer=setTimeout(()=>{st.textContent='STATUS: READY TO OPEN 🔓';st.classList.add('gate-ready');btn.classList.remove('moment-hidden');hearts(5)},1400)}function finishAudioGate(){hideMoment('audioGateOverlay');go(8)}"""
    s = s.replace('function q4(', js + 'function q4(', 1)

required = ['id="giftChoiceOverlay"','id="statsOverlay"','id="typingOverlay"','id="audioGateOverlay"','onclick="openGiftChoice()"','onclick="showPrideTyping()"','onclick="openAudioGate()"']
for token in required:
    if token not in s:
        raise SystemExit(f'Missing required token: {token}')

p.write_text(s, encoding='utf-8')
Path('marwa-fresh.html').write_text(s, encoding='utf-8')
Path('marwa-interactive.html').write_text(s, encoding='utf-8')
print('PATCH_OK')
